#!/bin/bash
# batch F1b: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/F1b.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/F1b.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
/usr/bin/python3 -I kb/bin/kb claim verify 686 --by kb-claims_tracks --evidence '2404.16270v1 article.tex L246-256: eq. CoordtEqs, coordinate-time equation of motion of each binary member (geodesic terms plus the self-gravity potential gradient).' || { echo FAILED 686; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 688 --by kb-claims_tracks --evidence '2404.16270v1 appendix.tex L117-134: 1PN N-body equations (eq. eab.1) and their restricted three-body form with the heavy body fixed at the origin; that F-hills does not implement them is the track'"'"'s statement.' || { echo FAILED 688; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 635 --by kb-claims_tracks --evidence '2404.16270v1: criterion alpha = a/R << 1 with R = (r/r_g)^(3/2) r_g (article L272-274); alpha ~ 1e-5 most of the time and up to 0.2 for the deepest encounters (L279); in the beta = 8.5 examples alpha ~ 0.1 briefly at pericentre (appendix L8, also L12); beta restricted to <= 10 because alpha >~ 0.1 becomes common (article L318).' --locator '2404.16270v1:article.tex:L272-274; 2404.16270v1:article.tex:L279; 2404.16270v1:appendix.tex:L8' || { echo FAILED 635; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 423 --by kb-claims_tracks --evidence '2406.11985v1 massratio_table.tex L21 (d/M = 1.979 and 0.990) and L30 (D/M = 12.93 and 11.96), within L9-30; masses m1 = m2 = 0.1, m3 = 0.8 and m1 = m2 = 0.05, m3 = 0.9 give q = 4.0 and 9.0 and a_b = d/(m1+m2) = 9.9 [arithmetic]. D/r_t = 4.1 and 5.8 are F'"'"'s run F-hills-20261115-045435-f62d553, not redone here.' || { echo FAILED 423; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 426 --by kb-claims_tracks --evidence '2406.11985v1 TBH3.tex L686-688: starting the third hole closer than about 30 M gives prompt disruption; L710: the sequence could be continued at least to 128:1:1.' --locator '2406.11985v1:TBH3.tex:L686-688; 2406.11985v1:TBH3.tex:L710' || { echo FAILED 426; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 428 --by kb-claims_tracks --evidence '2308.07365v1 TBH.tex L66: third hole at D = 30 M, inner separation d = 8 M; L1040-1047: merger delay ~ 1/D^2.5 and prompt breakdown when the third hole starts closer than about 30 M.' || { echo FAILED 428; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 430 --by kb-claims_tracks --evidence '2505.03934v2: all black holes have equal mass (L246), so the single hole has half the binary mass; L108: even of order a thousand scattering runs is not feasible in NR; L110: a few selected binary-single cases with BAM.' --locator '2505.03934v2:apssamp.tex:L108; 2505.03934v2:apssamp.tex:L110; 2505.03934v2:apssamp.tex:L246' || { echo FAILED 430; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 432 --by kb-claims_tracks --evidence '2505.03934v2: ADM mass 0.5 at each puncture (L246); grid tables L270-290 list spacings h_0..h_10 (11 levels) with finest h_10 = 0.00781 to 0.02344 M.' --locator '2505.03934v2:apssamp.tex:L246; 2505.03934v2:apssamp.tex:L270-290' || { echo FAILED 432; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 439 --by kb-claims_tracks --evidence '2505.01495v2 abstract L106-108: first full-GR evolution of a compact cluster of 25 equal-mass nonspinning black holes; one hole ejected with large velocity after a several-body interaction.' --locator 2505.01495v2:apssamp.tex:L106-108 || { echo FAILED 439; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 448 --by kb-claims_tracks --evidence '1203.6185v1 abstract L29-43: a perturbative scheme for a binary in the potential of a massive black hole, explicitly instead of a fully relativistic three-body simulation.' --locator 1203.6185v1:bbbhPRD.tex:L29-43 || { echo FAILED 448; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/F1b_annot.tsv || { echo FAILED annotate; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim check --id 686 688 423 428 --by kb-claims_tracks || { echo FAILED check; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/F1b.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
